let selectedUser='',selectedTheme='',modal=null,interval=null;
let session=null;
try { session=JSON.parse(localStorage.getItem(STORAGE)||'null'); } catch(_){}
const q=(sel,el=document)=>el.querySelector(sel);
const allMessages=()=>[...document.querySelectorAll('.public_message[data-user]')].filter(x=>q('.username__wrapper',x));
const getUsers=()=>{const seen=new Set(),out=[];for(const el of allMessages().reverse()){const id=el.dataset.user,name=q('.username__wrapper',el)?.textContent.trim();if(id&&name&&!seen.has(id)){seen.add(id);out.push({id,name});}}return out;};
function ownUser(){const selectors=['#my-profile .username__wrapper','#profile-modal .username__wrapper','.my-profile .username__wrapper','.profile-me .username__wrapper'];const name=selectors.map(s=>q(s)?.textContent.trim()).find(Boolean);if(!name)return '';const matches=getUsers().filter(u=>u.name===name);return matches.length===1?matches[0].id:'';}
function state(){const now=Date.now();if(session&&now<session.end)return 'active';if(session&&now<session.end+COOLDOWN)return 'cooldown';return 'ready';}
function seconds(ms){return Math.max(0,Math.ceil(ms/1000));}
function clock(ms){const sec=seconds(ms);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(session));return true;}catch(e){console.warn('Preview storage failed',e);return false;}}
function clearPreview(){document.querySelectorAll(`.public_message[${ACTIVE_ATTR}]`).forEach(el=>el.removeAttribute(ACTIVE_ATTR));}
function applyPreview(){clearPreview();if(state()!=='active')return;const user=session.user,theme=session.theme;for(const el of allMessages())if(el.dataset.user===user)el.setAttribute(ACTIVE_ATTR,theme);}
function status(msg){const el=modal&&q('.dw-status',modal);if(el)el.textContent=msg;}
